package com.example.aiassistant.ai;

import org.springframework.ai.chat.model.ChatModel;
import org.springframework.ai.chat.prompt.Prompt;
import org.springframework.stereotype.Service;

@Service
public class ChatService {
    private final ChatModel chatModel;

    public ChatService(ChatModel chatModel) {
        this.chatModel = chatModel;
    }

    public String chat(String userMessage) {
        String systemPrompt = "You are a helpful AI assistant. Be concise and friendly.";
        String fullPrompt = systemPrompt + "\n\nUser: " + userMessage;
        return chatModel.call(new Prompt(fullPrompt)).getResult().getOutput().getText();
    }
}
