        System.out.println(leetCode100.subsets(list));
    }

    public List<List<Integer>> subsets(List<Integer> nums) {
        List<List<Integer>> result = new ArrayList<>();
        if (nums == null || nums.size() == 0) {
            return result;
        }
        List<Integer> path = new ArrayList<>();
        dfs(nums, 0, path, result);
        return result;
    }

    private void dfs(List<Integer> nums, int index, List<Integer> path, List<List<Integer>> result) {
        if (index == nums.size()) {
            result.add(new ArrayList<>(path));
            return;
        }
        path.add(nums.get(index));
        dfs(nums, index + 1, path, result);
        path.remove(path.size() - 1);
        dfs(nums, index + 1, path, result);
    }
}
